#include <iostream>
#include <algorithm>

constexpr long long MOD = 1000000007;

long long dp[55][55][205]{};
long long c[55][55]{};

int main() {
    int n, lim;
    std::cin >> n >> lim;

    int A = 0, B = 0;
    for (int i = 0; i < n; ++i) {
        int fk;
        std::cin >> fk;
        if (fk == 50) {
            ++A;
        } else {
            ++B;
        }
    }

    dp[A][B][0] = 1;
    c[0][0] = 1;

    for (int i = 1; i <= 50; ++i) {
        for (int j = 0; j <= i; ++j) {
            c[i][j] = (j > 0 ? c[i - 1][j - 1] : 0)
                    + (j < i ? c[i - 1][j] : 0);
        }
    }

    for (int k = 1; k <= 4 * n; ++k) {
        for (int i = A; i >= 0; --i) {
            for (int j = B; j >= 0; --j) {
                const int side = k % 2;
                dp[i][j][k] = 0;

                if (side) {
                    for (int ii = i; ii <= A; ++ii) {
                        int f = lim - (ii - i) * 50;
                        if (f >= 0) {
                            f /= 100;
                            f = std::min(f + j, B);

                            for (int jj = j; jj <= f; ++jj) {
                                if (i != ii || j != jj) {
                                    dp[i][j][k] +=
                                        dp[ii][jj][k - 1] *
                                        c[ii][ii - i] % MOD *
                                        c[jj][jj - j] % MOD;
                                    dp[i][j][k] %= MOD;
                                }
                            }
                        }
                    }
                } else {
                    for (int ii = 0; ii <= i; ++ii) {
                        int f = lim - (i - ii) * 50;
                        if (f >= 0) {
                            f /= 100;
                            f = std::max(j - f, 0);

                            for (int jj = f; jj <= j; ++jj) {
                                if (i != ii || j != jj) {
                                    dp[i][j][k] +=
                                        dp[ii][jj][k - 1] *
                                        c[A - ii][i - ii] % MOD *
                                        c[B - jj][j - jj] % MOD;
                                    dp[i][j][k] %= MOD;
                                }
                            }
                        }
                    }
                }

                if (dp[0][0][k]) {
                    std::cout << k << '\n' << dp[0][0][k] << '\n';
                    return 0;
                }
            }
        }
    }

    std::cout << "-1\n0\n";
    return 0;
}

